// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint128 depositAmount, uint8 withdrawalRounds) public {
        vm.assume(depositAmount > 0);
        vm.assume(withdrawalRounds > 0);
        address actor = address(0x1000);
        vm.deal(actor, type(uint128).max);
        vm.startPrank(actor);
        c.addToBalance{value: depositAmount}();
        for (uint256 i = 0; i < withdrawalRounds; i++) {
            c.withdrawBalance();
        }
        vm.stopPrank();
        assertTrue(c.getBalance(actor) == address(c).balance);
    }
}
